      const st = gst(), miss = gmiss(), seen = gseen();
      Q.forEach((q, i) => { if (q.k !== 'g' || ans[i] == null) return; const c = st[q.cat] || (st[q.cat] = { a: 0, c: 0 }); const prev = counted[q.key]; if (prev) { c.a--; if (prev.ok) c.c--; } counted[q.key] = { ok: ans[i] === q.answer }; c.a++; seen[q.key] = 1; if (ans[i] === q.answer) { c.c++; delete miss[q.key]; } else miss[q.key] = 1; });
      store.set('sff-gstats', st); store.set('sff-missed', miss); store.set('sff-gseen', seen);
      const cOk = Q.filter((q, i) => q.k === 'c' && ans[i] === q.answer).length, gOk = Q.filter((q, i) => q.k === 'g' && ans[i] === q.answer).length;
      if ((qmode === 'full' || qmode === 'comp') && ans.some(a => a != null)) { const all = scores(); all[s.id] = Math.max(all[s.id] || 0, cOk); store.set('sff-scores', all); }
