        const row = (q, i) => { const ok = ans[i] === q.answer; return `<div class="qri ${ok ? 'ok' : 'bad'}"><b>${ok ? '✓' : '✗'}</b><div>${esc(q.q)}<small>${ok ? esc(q.options[q.answer]) : `You: ${ans[i] == null ? '(skipped)' : esc(q.options[ans[i]])} · Correct: ${esc(q.options[q.answer])}`}</small>${!ok && q.why ? `<small class="why">${esc(q.why)}</small>` : ''}</div></div>`; };
        const wrongQs = Q.filter((q, i) => ans[i] !== q.answer), st = gst(), cats = Object.keys(st).filter(c => st[c].a > 0).sort((x, y) => pct(st[x]) - pct(st[y]));
        const area = c => { const v = pct(st[c]), lab = v < .6 ? ['Needs practice', 'low'] : v < .85 ? ['Getting there', 'mid'] : ['Strong', 'hi']; return `<div class="qar"><span class="qan">${esc(c)}</span><span class="qab"><i class="${lab[1]}" style="width:${Math.round(v * 100)}%"></i></span><span class="qal ${lab[1]}">${lab[0]}</span></div>`; };
        const label = { full: '', comp: 'Comprehension retry', gram: 'Grammar retry', missed: 'Retrying what you missed', practice: 'Grammar practice' }[qmode];
        panel.innerHTML = `<div class="qw"><div class="hd">${title}<span class="ic"></span></div><div class="end qres">${label ? `<div class="mute" style="font-size:.8rem;text-transform:uppercase;letter-spacing:.06em">${label}</div>` : ''}<div class="big">${tot} / ${Q.length}</div><p><b>${msg}</b></p>
          <div class="qsplit">${cN ? `<span><b>${cOk}/${cN}</b> Comprehension</span>` : ''}${gN ? `<span><b>${gOk}/${gN}</b> Grammar</span>` : ''}</div>
          <div class="qact">${qmode === 'practice' ? '<button class="btn" id="b-pr">Practice again</button><button class="btn ghost" id="b-full">Back to this story’s quiz</button>' :
            `${wrongQs.length ? '<button class="btn" id="b-miss">Retry what you missed</button><button class="btn ghost" id="b-nb">Save ' + wrongQs.length + ' missed to your notebook</button>' : ''}${baseC.length ? '<button class="btn ghost" id="b-c">Retry comprehension</button>' : ''}${baseG.length ? '<button class="btn ghost" id="b-g">Retry grammar</button>' : ''}${cats.length ? '<button class="btn ghost" id="b-pr">Practice weak spots</button>' : ''}`}</div>
          ${cats.length ? `<div class="qareas"><h5>Your grammar areas</h5>${cats.slice(0, 6).map(area).join('')}${cats.length > 6 ? `<div class="mute" style="font-size:.78rem">…and ${cats.length - 6} more</div>` : ''}</div>` : ''}
          <p class="mute" style="font-size:.78rem;margin:6px 0 0">Progress is saved on this device.</p>
          <div class="qrl">${cN ? '<h5>Comprehension</h5>' + Q.map((q, i) => q.k === 'c' ? row(q, i) : '').join('') : ''}${gN ? '<h5>Grammar</h5>' + Q.map((q, i) => q.k === 'g' ? row(q, i) : '').join('') : ''}</div></div><button class="nv l" id="pv">‹</button></div>`;
        const on = (id, fn) => { const e = panel.querySelector('#' + id); if (e) e.onclick = fn; };
