    const GR = ((DATA.grammar || {})[s.id]) || [], plain = h => String(h).replace(/<[^>]+>/g, '');
    const exFor = w => { const k = plain(w).toLowerCase().replace(/^(el|la|los|las|un|una)\s+/, '').trim(); if (!k) return null; const l = s.lines.find(x => plain(x[0]).toLowerCase().includes(k)); return l ? [plain(l[0]).replace(/\n/g, ' '), plain(l[1]).replace(/\n/g, ' ')] : null; };
