    const ESS = ((DATA.essentials || {})[s.level.toLowerCase()] || []).map(e => ({ topic: '★ ' + e.topic, explain: e.explain, examples: e.examples })), gDeck = () => [...GR, ...ESS].flatMap(g => [{ t: 'g', f: g.topic, b: g.explain, exs: g.examples || [] }, ...(g.examples || []).slice(0, 2).map(e => ({ t: 'e', f: plain(e[0]), b: plain(e[1]), topic: g.topic }))]);
    const mkDeck = k => k === 'vocab' ? vDeck() : k === 'grammar' ? gDeck() : [...vDeck(), ...gDeck()];
    // Flashcard state: kind = deck ('all'|'vocab'|'grammar'), ci = card index, flipped, mode = 'study' or 'practice'
    // (guess, flip, mark right/wrong), wrong = cards marked wrong this round
    let kind = 'all', deck = mkDeck(kind), ci = 0, flipped = false, mode = 'study', front = 'front', insOpen = false, wrong = [];
    const lab = w => ({ v: 'WORD', g: 'GRAMMAR', e: 'EXAMPLE' }[w.t]) + (w.t === 'e' ? ' · ' + esc(w.topic) : '') + (w.t === 'g' ? ' · ' + esc(w.f) : '');
    const face = (w, back) => {
      if (w.t === 'g') return back ? `<div class="rvx">${esc(w.b)}</div>${w.exs.length ? `<ul class="rve">${w.exs.slice(0, 3).map(e => `<li>${esc(plain(e[0]))}<small>${esc(plain(e[1]))}</small></li>`).join('')}</ul>` : ''}` : `<div class="rvt">${esc(w.f)}</div><div class="rvh">Tap the card to see the rule</div>`;
      const txt = back ? w.b : w.f;
      return `<div class="rvt">${esc(txt)}</div>${w.t === 'v' && back && w.ex ? `<ul class="rve one"><li>${esc(w.ex[0])}<small>${esc(w.ex[1])}</small></li></ul>` : ''}${back ? '' : '<div class="rvh">Tap the card to flip it</div>'}`;
    };
    // Draw the flashcard screen (or the end screen, which also sets the "cards" progress flag). Wrong vocab cards
