        panel.innerHTML = `<div class="qw"><div class="hd">${title}<span class="ic"></span></div><div class="end qres"><div class="big">${prac ? (wrong.length ? wrong.length + ' to review' : '🎉') : '✓'}</div><p><b>${prac ? (wrong.length ? `${wrong.length} card(s) marked wrong.` : 'All cards correct!') : `You went through all ${deck.length} cards.`}</b></p><div class="qact"><button class="btn" id="rs">${prac && wrong.length ? 'Review wrong cards' : 'Go again'}</button>${prac ? '' : '<button class="btn ghost" id="rq">Quiz yourself</button>'}</div></div></div>`;
