        <div class="rvseg" role="tablist">${[['all', 'All'], ['vocab', 'Words'], ['grammar', 'Grammar']].map(([k, n]) => `<button data-k="${k}" role="tab" aria-selected="${kind === k}" class="${kind === k ? 'on' : ''}">${n} <span class="ct">${mkDeck(k).length}</span></button>`).join('')}</div>
