        acc.forEach(w => fb.push(['warn', `Accent check: “${w}” is usually written “${ACCENTS[w]}”.`]));
        const cnt = {}; words(t.toLowerCase()).forEach(w => { if (w.length > 3) cnt[w] = (cnt[w] || 0) + 1; });
        Object.entries(cnt).filter(e => e[1] >= 4).forEach(e => fb.push(['tip', `You used “${e[0]}” ${e[1]} times. Can you vary it?`]));
        if (lv !== 'A1' && !/\b(porque|pero|cuando|aunque|mientras|sin embargo|por eso|entonces|después|luego)\b/i.test(t)) fb.push(['tip', 'Try joining two ideas with a connector such as “porque”, “pero” or “cuando”.']);
